# pomodoro timer. generated by claude.
# typed by me, used for learning purposes.

import tkinter as tk

# settings
WORK_MIN = 25
SHORT_BREAK_MIN = 5
LONG_BREAK_MIN = 15
SESSIONS_BEFORE_LONG_BREAK = 4

#text colors
MODE_COLORS = {
    "Work": "#c0392b",
    "Short Break": "#27ae60",
    "Long Break": "#2980b9",
}

#app
class PomodoroApp:
    def __init__(self, root):
        self.root = root
        self.root.title("Pomodoro Timer")
        self.root.geometry("320x300")
        self.root.resizable(False, False)

        self.mode = "Work"
        self.time_left = WORK_MIN * 60
        self.running = False
        self.timer_id = None
        self.sessions_done = 0

        self.mode_label = tk.Label(root, text=self.mode, font=("Helvetica", 20, "bold"))
        self.mode_label.pack(pady=(20, 5))

        self.time_label = tk.Label(root, text="", font=("Helvetica", 48))
        self.time_label.pack(pady=10)

        self.session_label = tk.Label(root, text="", font=("Helvetica", 11))
        self.session_label.pack()

        button_frame = tk.Frame(root)
        button_frame.pack(pady=20)

        self.start_button = tk.Button(button_frame, text="Start", width=8,
                                      command=self.toggle_timer)
        self.start_button.grid(row=0, column=0, padx=5)

        self.reset_button = tk.Button(button_frame, text="Reset", width=8,
                                      command=self.reset)
        self.reset_button.grid(row=0, column=1, padx=5)

        self.skip_button = tk.Button(button_frame, text="Skip", width=8,
                                     command=self.skip)
        self.skip_button.grid(row=0, column=2, padx=5)

        self.update_display()

    # display

    def update_display(self):
        minutes, seconds = divmod(self.time_left, 60)

        self.time_label.config(text=f"{minutes:02d}:{seconds:02d}")
        self.mode_label.config(text=self.mode, fg=MODE_COLORS[self.mode])
        self.session_label.config(text=f"Sessions completed: {self.sessions_done}")

    # start / pause
    def toggle_timer(self):
        if self.running:

            self.running = False
            self.root.after_cancel(self.timer_id)
            self.start_button.config(text="Resume")
        else:
            self.running = True
            self.start_button.config(text="Pause")
            self.timer_id = self.root.after(1000, self.tick)

    # countdown
    def tick(self):
        self.time_left -= 1
        self.update_display()

        if self.time_left <= 0:
           self.finish_session()
        else:
            self.timer_id = self.root.after(1000, self.tick)

    def finish_session(self):
        self.root.bell()

        if self.mode == "Work":
            self.sessions_done += 1
            
            if self.sessions_done % SESSIONS_BEFORE_LONG_BREAK == 0:
                self.set_mode("Long Break")
            else:
                self.set_mode("Short Break")

        else:
            self.set_mode("Work")

    # switch to new mode
    def set_mode(self, new_mode):
        self.mode = new_mode

        if new_mode == "Work":
            self.time_left = WORK_MIN * 60
        elif new_mode == "Short Break":
            self.time_left = SHORT_BREAK_MIN * 60
        else:
            self.time_left = LONG_BREAK_MIN * 60

        self.running = False
        self.start_button.config(text="Start")
        self.update_display()

    # reset button
    def reset(self):
        if self.running:
            self.root.after_cancel(self.timer_id)
        self.set_mode(self.mode)

    # skip button
    def skip(self):
        if self.running:
            self.root.after_cancel(self.timer_id)
        if self.mode == "Work":
            self.set_mode("Short Break")
        else:
            self.set_mode("Work")

# program entry point
if __name__ == "__main__":
    root = tk.Tk()
    app = PomodoroApp(root)
    root.mainloop()


    
                
